import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/getisord/getisord_crime_second_half_2016.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
df['crime_rate_value'] = df['crime_rate_value'].fillna(df['crime_rate_value'].mean())

# Create a neighbors list
neighbors = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Calculate the combined total
combined_totals = {}
for borough in df['borough']:
    total = df.loc[df['borough'] == borough, 'crime_rate_value'].values[0]
    for neighbor in neighbors[borough]:
        total += df.loc[df['borough'] == neighbor, 'crime_rate_value'].values[0]
    combined_totals[borough] = total

# Calculate the citywide average
citywide_average = np.mean(list(combined_totals.values()))

# Apply the Getis-Ord Gi* method
z_scores = {}
for borough in combined_totals:
    z = (combined_totals[borough] - citywide_average) / np.std(list(combined_totals.values()))
    z_scores[borough] = z

# Identify hot and cold spots
hot_spots = {borough: z for borough, z in z_scores.items() if abs(z) > 1.96}
cold_spots = {borough: z for borough, z in z_scores.items() if abs(z) > 1.96 and borough not in hot_spots}

# Print the results
data_points_used = len(combined_totals)
results = []
for borough, z in hot_spots.items():
    results.append(f"{borough} (HOT, Gi*={z})")
for borough, z in cold_spots.items():
    results.append(f"{borough} (COLD, Gi*={z})")
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {', '.join(results)}")
